import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { fetchMealsApi, addMealApi, deleteMealApi } from "../../api/mealsApi";

export const useMeals = (date, token) => {
  const queryClient = useQueryClient();

  // 🔹 Получение списка еды
  const { data: rows = [], isLoading: loading } = useQuery(
    ["meals", date],
    () => fetchMealsApi(token, date),
    {
      enabled: !!token,
    }
  );

  // 🔹 Добавление еды
  const addMealMutation = useMutation(
    ({ mealId, amount }) => addMealApi(token, mealId, amount),
    {
      onSuccess: (_, variables) => {
        // обновляем локальный кэш react-query, добавляя новую еду
        queryClient.setQueryData(["meals", date], (old = []) => [
          ...old,
          {
            id: Date.now(), // временный ID, позже сервер вернёт настоящий
            food_name: variables.mealId.name || "Food",
            amount: variables.amount,
          },
        ]);
      },
    }
  );

  // 🔹 Удаление еды
  const deleteMealMutation = useMutation(
    (mealId) => deleteMealApi(token, mealId),
    {
      onSuccess: (_, mealId) => {
        // убираем элемент из кэша
        queryClient.setQueryData(["meals", date], (old = []) =>
          old.filter(row => row.id !== mealId)
        );
      },
    }
  );

  const handleAddMeal = (mealId, amount) => {
    if (!mealId || !amount) return;
    addMealMutation.mutate({ mealId, amount });
  };

  const handleDeleteMeal = (mealId) => {
    deleteMealMutation.mutate(mealId);
  };

  return { rows, loading, handleAddMeal, handleDeleteMeal };
};
